 for name,content in OVERRIDE.items():
  f=src/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(content+'\n',encoding='utf8')
 for f in (ROOT/'tests/java247').rglob('*.java'):
  dest=src/f.relative_to(ROOT/'tests/java247');dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,dest)
 shutil.rmtree(src/'dev/settledlands/npc/client')
 files=sorted(src.rglob('*.java'));subprocess.run([str(java.resolve()),'-jar',str(ROOT/'tools/vendor/ecj-3.46.100.jar'),'-21','-encoding','UTF-8','-g:none','-nowarn','-cp',str(jar.resolve()),'-d',str(out),*map(str,files)],check=True)
